package com.android.messaging.ui.conversationlist;
import android.content.Context;import android.graphics.Typeface;import android.text.format.DateUtils;import android.util.AttributeSet;import android.view.View;import android.widget.FrameLayout;import android.widget.ImageView;import android.widget.TextView;import com.android.messaging.R;import com.android.messaging.sms.SmsRepository;import com.android.messaging.ui.ContactIconView;import com.android.messaging.util.AppPrefs;import com.android.messaging.util.UiUtil;
public class ConversationListItemView extends FrameLayout {private View swipeBg,container;private ImageView left,right;private ContactIconView icon;private TextView name,snippet,time,badge;public ConversationListItemView(Context c,AttributeSet a){super(c,a);} @Override protected void onFinishInflate(){super.onFinishInflate();swipeBg=findViewById(R.id.crossSwipeBackground);container=findViewById(R.id.swipeableContainer);left=findViewById(R.id.crossSwipeArchiveIconLeft);right=findViewById(R.id.crossSwipeArchiveIconRight);icon=findViewById(R.id.conversation_icon);name=findViewById(R.id.conversation_name);snippet=findViewById(R.id.conversation_snippet);time=findViewById(R.id.conversation_timestamp);badge=findViewById(R.id.unread_badge);}public void bind(SmsRepository.Conversation c){boolean dark=AppPrefs.isDark(getContext());name.setTextColor(dark?0xfff5f5f5:0xde000000);int detail=dark?0xffbdbdbd:0x8a000000;snippet.setTextColor(detail);time.setTextColor(detail);name.setText(c.title);String pre=c.type==android.provider.Telephony.Sms.MESSAGE_TYPE_INBOX?"":"You: ";snippet.setText(pre+(c.snippet==null?"":c.snippet.replace('\n',' ')));time.setText(com.android.messaging.util.MessageTimes.exact(c.date,android.text.format.DateFormat.is24HourFormat(getContext())));boolean unread=c.unread>0;name.setTypeface(Typeface.DEFAULT,unread?Typeface.BOLD:Typeface.NORMAL);snippet.setTypeface(Typeface.DEFAULT,unread?Typeface.BOLD:Typeface.NORMAL);snippet.setMaxLines(2);icon.bind(c.title,c.address);if(unread){badge.setVisibility(VISIBLE);badge.setText(c.unread>99?"99+":Integer.toString(c.unread));int badgeColor=AppPrefs.conversationColor(getContext(),c.address);badge.setBackground(UiUtil.circle(badgeColor));badge.setTextColor(UiUtil.readable(badgeColor));}else badge.setVisibility(GONE);resetSwipe();}public View swipeContainer(){return container;}public void showSwipe(boolean toLeft){swipeBg.setVisibility(VISIBLE);left.setVisibility(toLeft?GONE:VISIBLE);right.setVisibility(toLeft?VISIBLE:GONE);}public void resetSwipe(){if(container!=null){container.setTranslationX(0);container.setAlpha(1);}if(swipeBg!=null)swipeBg.setVisibility(GONE);}}
